"use strict";

/**
 * v3.5.5 (3P Matrix 4.5.4 parity): this list ships as a precompiled JSON string in SuspiciousDomains.default.js,
 * generated by tools/gen-data-defaults.mjs from data/SuspiciousDomains.json, and is parsed on its first
 * lookup (util/LazyJson.js) — never at service-worker start.
 *
 * SuspiciousDomains.js
 * Risk scores (0–100) for domains that are frequently used in malware delivery.
 * Higher score = stronger indicator of risk.
 *
 * Lookup is done against the full hostname AND the registered domain (last two labels),
 * so "raw.githubusercontent.com" is matched even if the download comes from a subdomain.
 *
 * The raw TABLE data lives in data/SuspiciousDomains.json (the
 * single source of truth) and this module only holds the lookup LOGIC. The
 * compiled-in default below is generated from that JSON (see
 * SuspiciousDomains.default.js's own header) and is the only data this
 * module ever loads at runtime — v3.3.0 (3P Matrix alignment item 18)
 * removed the remote-refresh mechanism (util/FilterDataLoader.js) that used
 * to call setData() here with a freshly-fetched copy. setData()/
 * resetToDefault() remain for tests, which still swap TABLE out directly.
 */
import { SuspiciousDomainsDefaultJson } from "./SuspiciousDomains.default.js";
import { lazyJson } from "./LazyJson.js";

export const SuspiciousDomains = (function () {

    // 3P Matrix 4.5.4 (perf P4): parsed on first lookup, not at service-worker start (util/LazyJson.js).
    const defaultData = lazyJson(SuspiciousDomainsDefaultJson);
    let TABLE = null;       // null = use the default (parsed on first use); setData() replaces it
    function data() { return TABLE === null ? (TABLE = defaultData()) : TABLE; }

    /**
     * Look up a hostname in the table.
     * Checks the full hostname first, then the registered domain (last two labels).
     * Returns { score, matchedDomain } or null if not found.
     */
    function lookup(hostname) {
        if (!hostname) return null;
        const h = hostname.toLowerCase();

        // Full hostname match (e.g. "raw.githubusercontent.com")
        if (data()[h] !== undefined) {
            return { score: data()[h], matchedDomain: h };
        }

        // Registered-domain match (last two labels)
        const parts = h.split(".");
        if (parts.length >= 2) {
            const reg = parts.slice(-2).join(".");
            if (data()[reg] !== undefined) {
                return { score: data()[reg], matchedDomain: reg };
            }
        }

        return null;
    }

    /**
     * Replace the in-memory table — used by tests to install a known
     * fixture or reset back to the bundled default. No production caller
     * remains since item 18 removed the remote-refresh mechanism; never
     * call this with unvalidated data.
     */
    function setData(newTable) {
        TABLE = newTable;
    }

    function resetToDefault() {
        TABLE = null;           // released: the next lookup goes back to the default
    }

    return { lookup, setData, resetToDefault };
})();
